import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.6 Intelligent Maximum Gross Output (In Development, Stability Unverified, Do Not Copy)","description":"","frontmatter":{"translationSource":{"title":"1.6智能最大毛产（开发中，不对稳定性负责，不要抄取！）","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/full-storage-oscillation-plan"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/full-storage-oscillation-plan"}]]},"headers":[],"relativePath":"full-storage-oscillation-plan.md","filePath":"logistics/src/page-JEibHxjUhjwaznRy5jp6oc.md"}'),o={name:"full-storage-oscillation-plan.md"};function s(r,e,l,p,d,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="_1-6-intelligent-maximum-gross-output-in-development-stability-unverified-do-not-copy" tabindex="-1">1.6 Intelligent Maximum Gross Output (In Development, Stability Unverified, Do Not Copy) <a class="header-anchor" href="#_1-6-intelligent-maximum-gross-output-in-development-stability-unverified-do-not-copy" aria-label="Permalink to &quot;1.6 Intelligent Maximum Gross Output (In Development, Stability Unverified, Do Not Copy)&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>JEibHxjUhjwaznRy5jp6oc</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=JEibHxjUhjwaznRy5jp6oc" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><u><em><strong>Do not copy this! Do not copy this! Do not copy this!</strong></em></u></span></p><p><span class="mark-red"><u><em><strong>These blueprints are in beta. They have yet to be optimized for copying, and the release version will fix some details. We discourage anyone outside the team from importing the blueprints. Beta layouts generally aren&#39;t eligible for troubleshooting, with some discretion. We aren&#39;t ready to provide full support and parts of the layout still need testing. Send feedback to the group&#39;s support team. Posting it directly on this page may upset a random member of the team. Please respect the work of the authors, support team, and other contributors. Thank you.</strong></em></u></span></p><p><span class="mark-sky_blue">斯改: I&#39;m completely burned out.</span></p><p>Arknights: Endfield blueprint [Jingyu Valley 1]. Copy share code EF01eaA51A90745eo9i8 to use it in game. <span class="mark-grey">(Rotate the view with the pond at the bottom. Put the Automation-Core at the far bottom right, place the blueprint flush right, and move the core into the gap. Set 2 core withdrawal ports as marked by the Control Ports. Connect the unlinked Conduit Manifold next to the core to 4 Fluid Pumps and the standard Conduit to 4 Inergen Pumps.)</span></p><p>Arknights: Endfield blueprint [Jingyu Valley 2]. Copy share code EF01I43623O5o9625o08 to use it in game. <span class="mark-grey">(Connect 8 Fluid Pumps as marked by the Control Ports.)</span></p><p>Arknights: Endfield blueprint [Wuling Unpowered Crucible + Stash]. Copy share code EF01E758e5AU2o0U3uIa to use it in game. <span class="mark-grey">(Rotate the view with the river at the bottom. Put the Automation-Core at the upper left and place the blueprint against the lower-right corner. Wait one minute, then keep only the Reactor Crucible and Protocol Stash.)</span></p><p>Arknights: Endfield blueprint [Wuling 1]. Copy share code EF0170i86UIio5uEO0Ai to use it in game. <span class="mark-grey">(Move the Automation-Core to the southeast corner before placing it.)</span></p><p>Arknights: Endfield blueprint [Wuling 2]. Copy share code EF01u289E854I05IAoOU to use it in game. <span class="mark-grey">(Connect 12 Fluid Pumps in total. On the Conduit Manifold between the two Control Ports, connect one pump per port</span><span class="mark-grey">.)</span></p><p>Arknights: Endfield blueprint [Wuling 3]. Copy share code EF013Eo0Oo42uaoa0579 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 4]. Copy share code EF01eaAo97uAI4I4oui8 to use it in game. <span class="mark-grey">(Connect 4 Inergen Pumps as marked by the Control Ports. Connect the free Conduit Outlet Manifold to the Xiragen line returning from Yinglung Pass. Use inlet and outlet manifolds the entire way.)</span></p><p>Arknights: Endfield blueprint [Wuling 5]. Copy share code EF014AE6e50E93i4Ea1A to use it in game. <span class="mark-grey">(Set 4 Automation-Core withdrawal ports as marked by the Control Ports.)</span></p><p>Arknights: Endfield blueprint [With Purification Node]. Copy share code EF012UO9i4aO08aEeIOo to use it in game. <span class="mark-grey">(Connect 1 Xircon Effluent conduit and 3 Sewage conduits as marked by the Control Ports.)</span></p><p>Arknights: Endfield blueprint [Without Purification Node]. Copy share code EF01A67uai873E2u9ieO to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 1]. Copy share code EF0170iOai69U5I8O0Ai to use it in game. <span class="mark-grey">(Put the Automation-Core at the lower left before placing the blueprint, then insert it into the layout. From top to bottom, the right-hand conduits take </span><span class="mark-red">2 Acid Pumps, 2 Acid Pumps, 2 Acid Pumps, 1 Fluid Pump, 1 Acid Pump, 1 Inergen Pump, Xiragen from Si&#39;s Painting, Xiragen from Cedar Forest, Xiragen returning to the main base, and Xiragen from the North Wuling Exclusion Zone</span><span class="mark-grey">. Leave the corresponding conduits unused if you&#39;re skipping the Cedar Forest or Si&#39;s Painting feed or the return to the main base.)</span></p><p>Arknights: Endfield blueprint [Yinglung Pass 2]. Copy share code EF014AEuUEei531iEa1A to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 3]. Copy share code EF01u289E854I094AoOU to use it in game.</p><p>Full-map EnKAD simulation (early-morning build from November 16 <a href="https://beta.enka.network/endfield/aic/?id=R9u8B1x2S8K8r9" target="_blank" rel="noreferrer">https://beta.enka.network/endfield/aic/?id=R9u8B1x2S8K8r9</a>).</p><details><summary>International servers (early-morning build from November 16, provided by 浅仓透)</summary><p>Asia server</p><p>Arknights: Endfield blueprint [Jingyu Valley 1]. Copy share code EFO018Ie5I98ii1iUI73 to use it in game.</p><p>Arknights: Endfield blueprint [Jingyu Valley 2]. Copy share code EFO01I3A23aIUU9E5o08 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling Unpowered Crucible + Stash]. Copy share code EFO01Ue30e4U88OI7Oa8 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 1]. Copy share code EFO01O4ai43O11I79oe4 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 2]. Copy share code EFO01u8UE81u7702AoOU to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 3]. Copy share code EFO018Ie5I98ii127UI73 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 4]. Copy share code EFO01oui4u0oAA6uIieO to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 5]. Copy share code EFO018Ie5I98ii19UI73 to use it in game.</p><p>Arknights: Endfield blueprint [With Purification Node]. Copy share code EFO01eAo1AEeII47oAi8 to use it in game.</p><p>Arknights: Endfield blueprint [Without Purification Node]. Copy share code EFO019aE8aA9OOe15uI2 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 1]. Copy share code EFO01I3A23aIUU9775o08 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 2]. Copy share code EFO01iUI6UOiuu2eo72U4 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 3]. Copy share code EFO01oui4u0oAA63oIieO to use it in game.</p><p>Europe and Americas servers</p><p>Arknights: Endfield blueprint [Jingyu Valley 1]. Copy share code EFO01o08Ei5u276EIieO to use it in game.</p><p>Arknights: Endfield blueprint [Jingyu Valley 2]. Copy share code EFO0136u47Eo5AaU0579 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling Unpowered Crucible + Stash]. Copy share code EFO011ea84I93OUa34O7 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 1]. Copy share code EFO014o5e6AE7a3aE71A to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 2]. Copy share code EFO01eE79oaA6342oAi8 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 3]. Copy share code EFO0136u47Eo5AaO0579 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 4]. Copy share code EFO018932eOI4U1iUI73 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 5]. Copy share code EFO01IaoOA43Ee9E5o08 to use it in game.</p><p>Arknights: Endfield blueprint [With Purification Node]. Copy share code EFO01U4A139eaIOI7Oa8 to use it in game.</p><p>Arknights: Endfield blueprint [Without Purification Node]. Copy share code EFO01O3EUae4A9I79oe4 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 1]. Copy share code EFO01o08Ei5u276uIieO to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 2]. Copy share code EFO018932eOI4U19UI73 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 3]. Copy share code EFO01eE79oaA6347oAi8 to use it in game.</p></details><p><span id="source-block-wt8iPy0gMDFywV7KEmhkoR"></span></p><h2 id="video-script" tabindex="-1">Video Script <a class="header-anchor" href="#video-script" aria-label="Permalink to &quot;Video Script&quot;">​</a></h2><p>About the title:</p><p><span class="mark-grey">#言: I&#39;ve got a </span><span class="mark-grey"><s>brilliant</s></span><span class="mark-grey"> idea: “!? Getting Ready for 1.7 with Automatic Balancing.”</span></p><p>#ko鸟: To prepare for 1.7, how can the rear bases keep producing while the front gets first call on Cuprium and Xiranite? Fill material storage first. The front takes what it needs, and the rear turns the rest into products. <s>Aren&#39;t stock redistribution vouchers more important than the front line?</s></p><p><span id="source-block-YS3tBMxxg8McQAfMF35GpN"></span></p><h3 id="production-line-showcase" tabindex="-1">Production Line Showcase <a class="header-anchor" href="#production-line-showcase" aria-label="Permalink to &quot;Production Line Showcase&quot;">​</a></h3><p><strong>How This Build Improves on the Last</strong><br> The 1.5 factory achieved automatic balancing by keeping Xiranite and Cuprium stock at 0. That had drawbacks.<br> Players found that having 0 Xiranite in storage made it inconvenient to supply quests and craft power poles.<br> With 0 Xiranite stock, withdrawal-port behavior also occasionally broke automatic balancing. Combined with other handling errors, this could break the Xircon line.<br><span class="mark-grey"># Visual: Scroll through the relevant section of the 1.5 gross-output document.</span><br> The new build first revises the Xircon line so outside disturbances cannot damage it irreversibly.<br><span class="mark-grey"># Visual: Mock up a thumbnail for the resilient Xircon line video with an online template.</span><br> It also changes how automatic balancing works. Xiranite and Cuprium now balance at full storage.<br><span class="mark-grey"># Visual: Show the full-Xiranite oscillation module. Add a note nearby: “The complicated layout in the demo is optional. It supports deposits via a Protocol Stash.”</span><br><span class="mark-grey"># Small caption: “The design prevents deposits from nonproduction branches from crowding out production deposits when storage is full.”</span><br> The layout uses fewer pumps at the main base and leaves all of Marker Stone free.<br><span class="mark-grey"># Visual: Show an overhead view of the main base&#39;s pumps on the left and a surprised Xiao Chen over the empty Marker Stone on the right.</span><br> People asked how they could make use of that free space after the last video. This time we&#39;ll provide prefab modules and explain how to use them.<br><span class="mark-grey"># Visual: Show an overhead view of the Marker Stone prefab modules.</span><br> Full-storage balancing lets this line accommodate a much wider range of discretionary withdrawals than the 1.5 design. If an event like Integrated Aid needs 300+/min of a material again, players can take it without flipping any machines on or off.<br><span class="mark-grey"># Visual: Maybe a few memes poking fun at the old factory?</span><br> Other changes include a Yinglung Pass layout that tolerates extreme copper input and a disposal module that is more forgiving of operator errors.<br><span class="mark-grey"># Visual: Match each part of the narration with the corresponding overhead view.</span><br> The module walkthrough in a separate part of the video will cover these details.</p><p><strong>A Closer Look at the Features (Especially the Module Demos)</strong></p><p>Expectations for the audience: to leave positive comments in the comment section, for example; to bring most questions to the Q&amp;A site and the group chats, and to make clear that we lack the capacity to answer each one individually; and, on noticing that the comment section and even group members contain many incorrect replies, to affirm the helpful spirit first, then point out that wrong replies cause confusion, and finally not to condemn anyone outright but to further suggest that anyone with questions go to the group or the Q&amp;A site and treat the Q&amp;A staff&#39;s answers as authoritative—the staff may not be absolutely correct, but it is undeniable that they are more familiar with the production line than most people and can pass questions on to the developers at any time.</p><p><span id="source-block-UU4P5kkrLs4f54xy23COub"></span></p><h3 id="module-overview" tabindex="-1">Module Overview <a class="header-anchor" href="#module-overview" aria-label="Permalink to &quot;Module Overview&quot;">​</a></h3><p>Module overview</p><p><span id="source-block-dYxAeoUzEMt8b2FAbKujeO"></span></p><h3 id="how-automatic-balancing-works" tabindex="-1">How Automatic Balancing Works <a class="header-anchor" href="#how-automatic-balancing-works" aria-label="Permalink to &quot;How Automatic Balancing Works&quot;">​</a></h3><p><span id="source-block-VjRatZPY7VytfwEPSU53Zl"></span></p><h3 id="installation-tutorial" tabindex="-1">Installation Tutorial <a class="header-anchor" href="#installation-tutorial" aria-label="Permalink to &quot;Installation Tutorial&quot;">​</a></h3><p><span id="source-block-0rfOwq29K0j4iJLxK2zROW"></span></p><h2 id="production-line-layout" tabindex="-1">Production Line Layout <a class="header-anchor" href="#production-line-layout" aria-label="Permalink to &quot;Production Line Layout&quot;">​</a></h2><p><span id="source-block-pZevVPXGlCFmWxYpA22zV7"></span></p><h3 id="jingyu-valley" tabindex="-1">Jingyu Valley <a class="header-anchor" href="#jingyu-valley" aria-label="Permalink to &quot;Jingyu Valley&quot;">​</a></h3><p><span class="mark-red">Notes for the Jingyu Valley guided-placement script: because of Depot Loader priorities, once the Automation-Core is placed, neither its orientation nor its output item may be changed. Make absolutely sure it faces the direction you want (this affects the teleport arrival point and therefore the distance to the zipline) and outputs the correct item. Any change requires replacing the Loaders in the Liquid Xiranite oscillation module / placing the main base again. (But output labels can normally be deleted—wait, can they? Assume not for now. If you want to delete an output label, do it while placing Jingyu Valley, and place power generation first too.</span></p><p><strong>Current main constraint: 288 facilities (the facility count excludes pipes, pipe components and conveyor belts).</strong></p><p>12 Xiranite units with two Depot Loader inputs each (required)</p><p>2 Separator Cores (required)</p><p>3 Cuprium refining setups (oversupplied depot input, overflow shredding and fixed shredding all work and can be combined; a total of 2 Shredding Units would be excellent) (required)</p><p>Self-starting Yazhen/Jincao planting–seed-picking–shredding groups, one belt each (required)</p><p>Ferrium: 4 Refining Units with overflow to 3 Shredding Units</p><p>Fitting Units: 3 Pyrrolite, 1 Hetonite, 1 Ferrium</p><p>Pyrrolite Component Gearing Unit</p><p>SC Wuling Batteries (optional) (can be Sandleaf or Packaging)</p><p><span id="source-block-DWQoslYRbo23aoBVXH3XsK"></span></p><h4 id="blueprints" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h4><p><span class="mark-red">When saving a plan here, remember to mark which of the modules listed above are missing.</span></p><p>Oh no, it&#39;s painful without pictures. Should I import them all again? Or could you take screenshots and post them? TAT</p><p>Candidate results</p><p><span id="source-block-cQfQ9Yze9mNszYCHirnvQO"></span></p><h5 id="_13x286" tabindex="-1">13x286 <a class="header-anchor" href="#_13x286" aria-label="Permalink to &quot;13x286&quot;">​</a></h5><p>EF01o5u21aiU362EIieO</p><p>EF01A67024u8eEUI9ieO</p><p>EF014AE7uI60O3eIE71A 175; missing two Clean Water labels. Note: no Ferrium Parts.</p><p><span id="source-block-yGLCLRondLTdDxYZtwQJZU"></span></p><h5 id="ss" tabindex="-1">SS <a class="header-anchor" href="#ss" aria-label="Permalink to &quot;SS&quot;">​</a></h5><p>EF015i2O176iIuoeIoe</p><p>EF01ao60534oiA0oe5e</p><p>EF015i2O176iIu4eIoe 175. Note: no Ferrium Parts.</p><p>13x286 revision 1: 176; added one water supply for shredding, corrected plant placement for shredder warm-up, and added a Ferrium Parts Fitting Unit. Only the top and middle blueprints changed.</p><p>EF013Eo5097iIaAA0579</p><p>EF01U9eaE23oiO3I7Oa8</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-53917257dfbc9a54.q90-00f2379f6eb994aa.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-oGV4w9c54tkzUyK73km3p4"></span></p><h5 id="bear" tabindex="-1">bear <a class="header-anchor" href="#bear" aria-label="Permalink to &quot;bear&quot;">​</a></h5><p>EF015i2UO2EA1ua0eIoe</p><p>EF012UOe4O579855eIOo</p><p>EF014AE75EOU637UEa1A 178; includes a zipline support, complete labels and room for conduits. Note: no Ferrium Parts.</p><p>#言, comment: I&#39;m wondering whether one label could serve two pumps, which would make the manifold conduits easier to route. The advantages are room for 3 Thermal Banks and a very tidy layout.</p><p>SS revision 1: corrected water-pipe connections, moved the four essential conduits to matching positions on the same side, corrected some misconnected belts, and assigned one label per water supply.</p><p>EF01I43u18ui196U5o08</p><p>EF015i24oE4aouUEeIoe</p><p>EF01i1UA57Ao522U72U4</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7b7fba96431422e1.q90-208d72bdd3b7f208.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-zxUbO227j3Kb2WzqIHNVdW"></span></p><h5 id="collaboration-between-f-e-i-and-13×286" tabindex="-1">Collaboration between F.E.I. and 13×286 <a class="header-anchor" href="#collaboration-between-f-e-i-and-13×286" aria-label="Permalink to &quot;Collaboration between F.E.I. and 13×286&quot;">​</a></h5><p>EF01u28358Aiu09uAoOU</p><p>EF018OIo2I7U81u1UI73</p><p>EF01081au1E20i30E179; borrowed inspiration, 159, complete labels, 1 conduit and a zipline.</p><p>13x286 11.1</p><p>Fixed some small mistakes, such as a Protocol Stash placed instead of a Refining Unit, and one water pipe serving five facilities.</p><p>This blueprint now meets all requirements and is far ahead in facility-count compression. We can crown it king.</p><p>Note that this is the equivalent facility count. The conveyor-belt allowance has already been exceeded, so adding more facilities will make the count shoot up.</p><p>Revised twice now; I also ended up with one water pipe serving five facilities. Fixed(?) the four-items/one-second-stall problem. There is space to add Control Ports and water bottles as water-connection markers. Xiranite reaches full production in about seven minutes; the key to speeding it up is water for the Planting Unit at the far upper left.</p><p>Removed all water-pipe labels because they may cause the four-items/one-second stall when offline? Water-bottle labels were not added either. The 12 water pipes plus Inergen, the extra conveyor belts for individual Control Ports, and the labels would immediately use up another 16 facilities.</p><p>EF013Eo5097iIa3a0579</p><p>EF01eaA65OouU4OaoAi8</p><p>EF014AE7uI60O3uUE71A</p><p>The blueprint includes 153 equivalent facilities, a pipe-facility count of 26, and 46 minus water pipes [source shorthand]. It is fully functional, leaves an unfilled zipline space, and contains no logistics bridges. Supporting facilities are 4 pylons to power 12 water pumps, a pair of two-port conduits, the corresponding 11 water pipes and 3 Pipe Convergers. For frequent disassembly, conduit relays can be used at the cost of 4 extra facilities (two conduit sets). A manifold conduit can be replaced by two full-rate single-port conduits.</p><p>Note: I added the Ferrium return-to-depot route before the Parts Fitting Unit at the lower left myself. It is not functionally necessary and is not in the blueprint.</p><p>Changed Cuprium to be shredded first, with overflow going to the depot. Tidying this up saved another 1 facility and 1 pipe facility.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-811e996b30f8f0e1.q90-bae9cac359973699.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>SS revision three: 君 said overflow shredding and extra Ferrium Parts were unnecessary, so these were removed; some structures were optimized, and all exposed-pipe connections are conveniently positioned. Compressed into two blueprints with placement safeguards: both are 50*50, need no particular placement order, and cannot be placed the wrong way.</p><p>[Super Jingyu Valley 1] EF012UOEu5E6u899eIOo</p><p>[Super Jingyu Valley 2] EF015i24oE4aou2UeIoe</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-14ff90d6de20dc3e.q90-f9c9c563815492b6.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>13x286: Another revision, anyway. This is a temporary blueprint, pending someone fitting the Inergen conduit rerouting into it as well. The Clean Water conduit is also awkwardly positioned and needs extra piping. Its single label cannot be distinguished from an ordinary pump label, even though the conduit needs a full-rate water pipe.</p><p>EF01I43E61A789i65o08</p><p>EF01o5u21aiU36U0IieO</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e962b0c5906d166e.q90-c334c2491fb8e0d5.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>From SSnighter &amp; F.E.I &amp; 君 &amp; 13x: Revision complete. The conduit rerouting is at the lower left; an upper-left version also exists. It still uses the originally planned 11.5 pumps, with nowhere to use the spare half-pump. We have tried to keep placement to two blueprints.</p><p>Left: 62 machines, 97 other components (39 belts + 27 pipe components + 31 pipes).</p><p>Right: 89 machines, 71 other components (67 belts + 4 pipe components + 0 pipes).</p><p>Total: machines (151/288), other components (162/256), belts (106/96), pipe components (31/64), pipes (31/96). Actual machine usage: 151+10=161 machines. Including supporting AIC facilities—4 power poles + 12 pumps + 4 conduits—the total is 181 machines.</p><p>[Jingyu Valley left] EF01ao6uie529A25oe5e</p><p>[Jingyu Valley right] EF01A67024u8eEua9ieO</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-1ba2d8708f9f409f.q90-a00d8fe2f36ff702.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a1abd4a8b759ed20.q90-6fb80479ee77e3d5.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Old blueprints retained for reference:</p><p>13x286. Note: no Gearing Unit.</p><p>EF01I43E61A789E25o08</p><p>EF01I43E61A789Eu5o08</p><p>EF01ao6uie529AO7oe5e</p><p><span id="source-block-tkw1iLW0nUBPYwoeRyJccp"></span></p><h3 id="main-base" tabindex="-1">Main Base <a class="header-anchor" href="#main-base" aria-label="Permalink to &quot;Main Base&quot;">​</a></h3><p>Liquid Xiranite oscillation (4 crucibles<br> Input — water — by the river. Output — Liquid Xiranite — Xiranite Fluid-Gas Transmuting Unit.</p><p>2 fixed crucibles, requiring mixed medicine and one agricultural by-product<br> Input — water — by the river. Output — Liquid Xiranite — Xiranite Fluid-Gas Transmuting Unit. Output — medicinal fluid — basic-medicine line.</p><p>Mixed Xiragen/Aquagen production<br> Input — Liquid Xiranite — 2 fixed crucibles. Input — water — by the river / relayed through another water conduit. Output — Liquid Xiranite —</p><p>All-Condition Xircon</p><p>Cuprium refining with overflow to shredding: 8</p><p>Cuprium refining with two belts: 4</p><p>Cuprium refining with two belts, 2 coupled trash cans</p><p>Basic-medicine line starting from Ferrium</p><p>SC Wuling Batteries</p><p><span id="source-block-krXKbnL5O0kAIMgiAR5mXr"></span></p><h3 id="yinglung-pass" tabindex="-1">Yinglung Pass <a class="header-anchor" href="#yinglung-pass" aria-label="Permalink to &quot;Yinglung Pass&quot;">​</a></h3><p>Conduits placed outside — Solid-Gas Transmuting Units switched to overflow, plus Separator Cores</p><p><span id="source-block-Ces5lBPzmHuwJoEt14KUwj"></span></p><h4 id="blueprints-1" tabindex="-1">Blueprints <a class="header-anchor" href="#blueprints-1" aria-label="Permalink to &quot;Blueprints&quot;">​</a></h4><p>Arknights: Endfield blueprint [1], share code EF012UOe9a3UA8U4eIOo. Copy it and use it in the game. The blueprint split has a problem; revised code: EF01A67024u8eE1e9ieO. This set does not seem to be the latest progress, though. By 13x286.<br> Arknights: Endfield blueprint [2], share code EF018OI4eAaOE13uUI73. Copy it and use it in the game.<br> Arknights: Endfield blueprint [3], share code EF01Oe4Aa6oe7IuE9oe4. Copy it and use it in the game. Blueprint-split correction as above: EF01o5u21aiU36ioIieO.<br> Arknights: Endfield blueprint [4], share code EF0193aoE573ue4E5uI2. Copy it and use it in the game.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8878fe3704f1d2ed.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-454d47cf4cf6ae09.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a289fcc8acabc17a.q90-5c57931e17a963fb.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-wtaH6muc44xSRMXmWrcqDs"></span></p><h3 id="marker-stone" tabindex="-1">Marker Stone <a class="header-anchor" href="#marker-stone" aria-label="Permalink to &quot;Marker Stone&quot;">​</a></h3><p>Three-in-one integrated toolkit (Yuanyuan Manor + everyday supplies + reserve materials):</p><p>Blueprint outputs:<br> Farming materials: Bottled Duskberry Juice, Starch, Double-Yummy Feed, Sugar, Chili Powder, Flour and Rapeseed Oil.<br> Everyday exploration/puzzles: 799 Bottled Water, 799 Bottled Liquid Xiranite, 799 Bottled Liquid Heavy Xiranite.<br> Reserve materials: 3250 Yazhen Syringe [A], 3250 Cuprium Parts, 799 Ferrium Parts and 799 LC Wuling Batteries.</p><p>Power draw (including water and acid pumps): 415</p><p><span class="mark-blue">Blueprint code: EF013Eou7E3oEa96u0579</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0c22788646189df2.q90-ffa6175d4d81d5af.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-FBtPNvsLFil3Wtwnz99gI5"></span></p><h2 id="standalone-modules" tabindex="-1">Standalone Modules <a class="header-anchor" href="#standalone-modules" aria-label="Permalink to &quot;Standalone Modules&quot;">​</a></h2><p><span id="source-block-Z5vNKLZ8EC4EtG1KTC6C8F"></span></p><h3 id="xircon-line" tabindex="-1">Xircon Line <a class="header-anchor" href="#xircon-line" aria-label="Permalink to &quot;Xircon Line&quot;">​</a></h3><p>Arknights: Endfield blueprint [Single-Sided All-Condition Xircon], share code EF01u28U5Ie870a7AoOU. Copy it and use it in the game.<br> 15*21</p><p><span id="source-block-HUOTrAo1XGkxDqwoWUNxYD"></span></p><h3 id="heavy-xiranite" tabindex="-1">Heavy Xiranite <a class="header-anchor" href="#heavy-xiranite" aria-label="Permalink to &quot;Heavy Xiranite&quot;">​</a></h3><p>Arknights: Endfield blueprint [Four-Unit Heavy Xiranite], share code EF01I43EaUUUu9o45o08. Copy it and use it in the game.<br> 23*22, height 23</p><p><span id="source-block-A8b2BmNv3r8OczTH6mi4LB"></span></p><h3 id="copper-processing" tabindex="-1">Copper Processing <a class="header-anchor" href="#copper-processing" aria-label="Permalink to &quot;Copper Processing&quot;">​</a></h3><p>Arknights: Endfield blueprint [Temporary Refining], share code EF013Eo56eee8a510579. Copy it and use it in the game.<br> 12*21, double-sided</p><p>Arknights: Endfield blueprint [Separator Core], share code EF01U9ea48887OiI7Oa8. Copy it and use it in the game.<br> 12*15, double-sided</p><p>Arknights: Endfield blueprint [Two-Belt Cuprium], share code EF01o5uO5508u6330IieO. Copy it and use it in the game.</p><p>12*15, double-sided, exposed water pipes on both sides</p><p><span id="source-block-jb2LYfO4va5x22hZMk5JIm"></span></p><h3 id="sc-wuling-batteries" tabindex="-1">SC Wuling Batteries <a class="header-anchor" href="#sc-wuling-batteries" aria-label="Permalink to &quot;SC Wuling Batteries&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-87d2585d74b3e527.q90-8c276b21dca6cddc.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [No Face Detected], share code EF01ao605oa6oA4A6oe5e. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Reconnecting, Please Wait], share code EF015i2O1i52iu9EueIoe. Copy it and use it in the game.</p><p><span id="source-block-h3O6ZElo5DYvpwQqWExr9k"></span></p><h3 id="ferrium-processing" tabindex="-1">Ferrium Processing <a class="header-anchor" href="#ferrium-processing" aria-label="Permalink to &quot;Ferrium Processing&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abd42c7b4bee2263.q90-fcf8ba08a760fb80.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="K6uojhba5PhZY4h7JS1DHr"><p>赫塔 — Ferrium refining and shredding</p></div><p><span id="source-block-V6Z6WWObS8Sp9VROKaVcgK"></span></p><h3 id="xiranite" tabindex="-1">Xiranite <a class="header-anchor" href="#xiranite" aria-label="Permalink to &quot;Xiranite&quot;">​</a></h3><p><span class="mark-red">Where is it? Hurry up and bring it out!!!</span></p><p><span id="source-block-PSVH9EWPl3In6oiZbgmPV9"></span></p><h3 id="liquid-xiranite-full-storage-oscillation-module" tabindex="-1">Liquid Xiranite Full-Storage Oscillation Module <a class="header-anchor" href="#liquid-xiranite-full-storage-oscillation-module" aria-label="Permalink to &quot;Liquid Xiranite Full-Storage Oscillation Module&quot;">​</a></h3><p><span id="source-block-qFVfEvK9jO1NhKefnV1XSG"></span></p><h4 id="controlling-xiranite" tabindex="-1">Controlling Xiranite <a class="header-anchor" href="#controlling-xiranite" aria-label="Permalink to &quot;Controlling Xiranite&quot;">​</a></h4><p><span id="source-block-GiL6uZNnTppYmPRchrcBmr"></span></p><h4 id="controlling-water" tabindex="-1">Controlling Water <a class="header-anchor" href="#controlling-water" aria-label="Permalink to &quot;Controlling Water&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7c56052227e27422.q90-4b211e99002b0a11.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Filler: put 250 Jincao in every box except the unpowered one at the far left. Fill the unpowered tank with 4 miscellaneous items, and use enough Jincao Seeds to fill the length of the belt.</p><p>This should save a great many facilities, at the cost of only 4 pipe components. I have not compressed it yet, though ((</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-280aed2b84bcdf55.q90-653ca728b79d0e3c.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="cXD5Oa5klddFZoIT9qBbsU"><p>The priorities are as shown in the figure.</p></div><p>Initial compression is complete. Preparing the unpowered tank takes quite a while; I do not know whether to optimize that.</p><p><s>Arknights: Endfield blueprint [Wuling Unpowered Tank], share code EF015i2eii8O2uaa0eIoe. Copy it and use it in the game.</s></p><p><s>Arknights: Endfield blueprint [Oscillating Liquid Xiranite], share code EF01E75U77u25o56E3uIa. Copy it and use it in the game.</s></p><p><strong>Already optimized by the esteemed 君</strong></p><p>Liquid full-storage oscillation EF01u28O96Ueo00EAoOU<br> 14*27</p><p>It should work if placed as shown.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7cbaefd4b1cd885b.q90-fe1d3cb93912abf0.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Candidate: EF01A67024u8eE1O91eO, wide-range oscillation, 21*18. Adjustable oscillation range: 28s~108s (12 filler items) to 3948~4028s (62 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-feec2a836390e201.q90-8cbde867b109ae36.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>EF01o5u21aiU36iUIoeO is not narrow-range oscillation; its footprint is a little smaller, 20*18. Adjustable oscillation range: 34s~114s (12 filler items) to 114s~194s (13 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c2536bea61aa8e38.q90-ba4186b55889ea86.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>EF0193ao7UE51e345uI2, narrow-range version, 20*18. Adjustable oscillation range: 22s~62s (6 filler items) to 502s to 542s (20 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f420037eb66e90a.q90-117f16d292c0dd8e.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>EF01E75i83014oaU3uIa, ultra-narrow-range version, 20*18. Adjustable oscillation range: 8s~28s (7 filler items) to 308s~328s (22 filler items).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-fd8aab776a4fde48.q90-f329b117b2526f82.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-KGoyl1IImSJZnibL6nDWDF"></span></p><h3 id="xiragen" tabindex="-1">Xiragen <a class="header-anchor" href="#xiragen" aria-label="Permalink to &quot;Xiragen&quot;">​</a></h3><p><span id="source-block-bd3KuSLybokw1RKWgQVoj2"></span></p><h4 id="four-core-xiragen" tabindex="-1">Four-Core Xiragen <a class="header-anchor" href="#four-core-xiragen" aria-label="Permalink to &quot;Four-Core Xiragen&quot;">​</a></h4><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d65940d65c763827.q90-cba6bbcbbf5c1244.webp" alt="1.6 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [Two-Unit AND-Feed Xiragen], share code EF01Oe47ee3E4I3389oe4. Copy it and use it in the game.</p><p><span id="source-block-VI0K6hIG0gZuPIloebTgyJ"></span></p><h4 id="mixed-xiragen-aquagen-production" tabindex="-1">Mixed Xiragen/Aquagen Production <a class="header-anchor" href="#mixed-xiragen-aquagen-production" aria-label="Permalink to &quot;Mixed Xiragen/Aquagen Production&quot;">​</a></h4><p><span id="source-block-kWb3Jsyk9OsCbMnCJ8ZB5S"></span></p><h4 id="five-core-xiragen-alternative" tabindex="-1">Five-Core Xiragen (Alternative <a class="header-anchor" href="#five-core-xiragen-alternative" aria-label="Permalink to &quot;Five-Core Xiragen (Alternative&quot;">​</a></h4><p>Arknights: Endfield blueprint [Five Fluid-Gas Units], share code EF013Eou460iuau3U0579. Copy it and use it in the game.</p><p><span id="source-block-ngBpC9LcAExlpWVPW3ou0n"></span></p><h2 id="_1-6-intelligent-maximum-gross-output-factory-blueprints" tabindex="-1">1.6 Intelligent Maximum Gross Output Factory Blueprints <a class="header-anchor" href="#_1-6-intelligent-maximum-gross-output-factory-blueprints" aria-label="Permalink to &quot;1.6 Intelligent Maximum Gross Output Factory Blueprints&quot;">​</a></h2><p><span id="source-block-x4r3ynSbfH5jXWbQpLTlO3"></span></p><h3 id="blueprint-change-history-none-yet" tabindex="-1">Blueprint Change History<span class="mark-grey"> (None Yet)</span> <a class="header-anchor" href="#blueprint-change-history-none-yet" aria-label="Permalink to &quot;Blueprint Change History&lt;span class=&quot;mark-grey&quot;&gt; (None Yet)&lt;/span&gt;&quot;">​</a></h3><p><span id="source-block-kPGXWaNH5q7vvBvikrIAkM"></span></p><h3 id="blueprint-preparation-read-before-placing-the-blueprints-copied-from-1-5-and-awaiting-update" tabindex="-1"><strong>Blueprint Preparation</strong><span class="mark-red"><strong>(Read Before Placing the Blueprints)</strong></span><span class="mark-grey"> (Copied from 1.5 and Awaiting Update)</span> <a class="header-anchor" href="#blueprint-preparation-read-before-placing-the-blueprints-copied-from-1-5-and-awaiting-update" aria-label="Permalink to &quot;**Blueprint Preparation**&lt;span class=&quot;mark-red&quot;&gt; **(Read Before Placing the Blueprints)**&lt;/span&gt;&lt;span class=&quot;mark-grey&quot;&gt; (Copied from 1.5 and Awaiting Update)&lt;/span&gt;&quot;">​</a></h3><p><strong>Check your stocks:</strong></p><p><span class="mark-red"><u><strong>500+ Jincao, 500+ Yazhen, 500+ Sandleaf Seeds</strong></u></span><span class="mark-red"><strong></strong></span><span class="mark-red">1000+ Xiranite, 2000+ Cuprium Parts, 1000+ Amethyst Parts, 1000+ Ferrium Parts, 1000+ Origocrust, and 1000+ Originium Ore</span><span class="mark-grey"> (the non-underlined materials are for building facilities and are optional if you already have enough facilities)</span><span class="mark-red"><br></span> Also ensure <span class="mark-red"><strong>Pyrrolite and Hetonite storage are below capacity</strong></span><span class="mark-grey"> (#NH: Should we keep this? Is there anything else that must be below capacity?) (#言: I think Hetonite has to stay below capacity too.)</span></p><p><em>P.S. Valley and Wuling storage are shared when crafting facilities.</em></p><p><strong>Check your base upgrades:</strong></p><p><span class="mark-red"><u><strong>Max out</strong></u></span> <span class="mark-red"><strong>area expansion** and <strong>Depot Link segments</strong> at every base **except Marker Stone</strong></span><span class="mark-grey"> (Yinglung Pass can actually be two Depot Link levels short of the maximum).</span></p><p><span class="mark-red"><u>Unlock every technology except turrets</u></span><span class="mark-grey">. Some technologies have <span class="mark-red">prerequisite missions</span>, so check for missing ones and finish them.</span></p><p><strong>Check the North Wuling Exclusion Zone&#39;s</strong> <span class="mark-red"><strong>Xiragen vents</strong></span><strong>:</strong></p><p>Send <span class="mark-red">80+ Xiragen/min (at least the equivalent of 4 high-purity vents)</span> to Yinglung Pass<span class="mark-grey">. The end of this guide shows the Exclusion Zone connections. Join conduits with a length of pipe between them, as ends cannot face directly into one another.</span></p><p><strong>Also note the following when placing blueprints:</strong></p><ul><li><p>Before placing the next blueprint, <span class="mark-red">finish constructing every facility in the previous one: craft and submit the facilities; they must not remain </span><span class="mark-yellow">yellow</span><span class="mark-red"> construction ghosts.</span></p></li><li><p>Do not <span class="mark-red">make any changes inside these production lines beyond those demonstrated in the video</span><span class="mark-grey"> (including but not limited to: changing a control port&#39;s rate limit; modifying, re-placing, or deleting pipes and logistics components; modifying pipe/conduit connections; taking the Xiragen/Liquid Xiranite/Jincao Solution/Yazhen Solution out of the line) (if you want to modify something, ask in the group chat or in the bilibili comments)</span>.</p></li></ul><p>If you do not have enough Cuprium Part in storage, consider this blueprint:</p><p>Arknights: Endfield blueprint [Cuprium Part Preparation], sharing code EF012UOAUUI4O8UAeIOo. Copy it and use it in the game.</p><p><span class="mark-grey">Connect two Fluid Pumps to this blueprint. It produces 120 Cuprium Part/min. (Keep the power on~)</span></p><p><span id="source-block-fhmbvA6qu8cS8g71la2guN"></span></p><h3 id="jingyu-valley-place-before-wuling-city-awaiting-update" tabindex="-1">Jingyu Valley<span class="mark-red"> (Place Before Wuling City)</span><span class="mark-grey"> (Awaiting Update)</span> <a class="header-anchor" href="#jingyu-valley-place-before-wuling-city-awaiting-update" aria-label="Permalink to &quot;Jingyu Valley&lt;span class=&quot;mark-red&quot;&gt; (Place Before Wuling City)&lt;/span&gt;&lt;span class=&quot;mark-grey&quot;&gt; (Awaiting Update)&lt;/span&gt;&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-139b88922e99bac1.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="AaqXxVHC8n6EexRm28A6NE"><p>Sky King Flats layout</p></div><p><span class="mark-blue">First put the Automation-Core on the left.</span></p><p>Arknights: Endfield blueprint [Jingyu Valley 1]. Copy share code EF01o5uiE8UuA6E5I2eO to use it in game.</p><p><span class="mark-blue">Place the blueprint flush with the right, move the Automation-Core into the gap, and configure 2 core withdrawal ports as marked by the Control Ports. Join the conduits next to the core. Connect the manifold to 4 Fluid Pumps and the single-port conduit to 4 Inergen Pumps.</span><span class="mark-grey"> See the connection diagram below.</span></p><p><span class="mark-red">Merge the 4 Fluid Pumps feeding the manifold in pairs. Never put 3 pumps on one port.</span></p><p>Arknights: Endfield blueprint [Jingyu Valley 2]. Copy share code EF01A67uai873EeA91eO to use it in game.</p><p><span class="mark-blue">After placing the Jingyu Valley blueprints, connect 8 Fluid Pumps as marked by the Control Ports.</span></p><p><span class="mark-red">Because deposit ports have priorities, </span><span class="mark-red"><u><strong>keep the Automation-Core&#39;s orientation and output item fixed after placement</strong></u></span><span class="mark-red">. Confirm the orientation you want (it affects where you arrive when teleporting and therefore the distance to the zipline) and the correct output item. Changing either requires </span><span class="mark-red"><strong>replacing the deposit ports on the Wuling City Liquid Xiranite oscillation module or placing Wuling City again</strong></span><span class="mark-grey">. See the bottom of the FAQ for the port locations.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bf72b4bac4be46e5.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="1ZZ8LpewFc9nJ3tUYtsrPz"><p>External conduit connection diagram</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-97b2d6bb0c009548.q90-ec43f0df6e6b51ab.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="jf3sI7OOQAuXfLTX51PM2X"><p>Pump placement inside the Jingyu Valley pond</p></div><p><span id="source-block-XMEw3L2QCHFEV3PZItW98f"></span></p><h3 id="wuling-city-awaiting-update" tabindex="-1">Wuling City<span class="mark-grey"> (Awaiting Update)</span> <a class="header-anchor" href="#wuling-city-awaiting-update" aria-label="Permalink to &quot;Wuling City&lt;span class=&quot;mark-grey&quot;&gt; (Awaiting Update)&lt;/span&gt;&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4275f17712ee6fef.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="7YJtfsIqbDiQHurCYiaFfI"><p>Wuling main base layout</p></div><p><span class="mark-blue">First put the Automation-Core in the lower-right corner.</span></p><p>Arknights: Endfield blueprint [Wuling Unpowered Crucible + Stash]. Copy share code EF01E758e5AU2o0U3uIa to use it in game.</p><p><span class="mark-blue">Rotate the view with the river at the top and place the blueprint against the upper-left corner. Let all items enter for one minute, then keep the Reactor Crucible and Protocol Stash and remove the rest.</span></p><p>Arknights: Endfield blueprint [Wuling 1]. Copy share code EF0170i86UIio5uEO0Ai to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 2]. Copy share code EF01u289E854I05IAoOU to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 3]. Copy share code EF013Eo0Oo42uaoa0579 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 4]. Copy share code EF01eaAo97uAI4I4oui8 to use it in game.</p><p>Arknights: Endfield blueprint [Wuling 5]. Copy share code EF014AE6e50E93i4Ea1A to use it in game.</p><p><span class="mark-blue">Put the Automation-Core back and set up 4 core withdrawal ports as marked by the Control Ports.</span></p><p><span class="mark-blue">If you have connected the Purification Node or Yinglung–Wuling Xiragen, connect the conduits as shown below. If the Purification Node is not connected, remember to add sewage treatment yourself; choose one of the following two blueprints according to your situation.</span><span class="mark-grey"> (Use the second if you cannot follow this.)</span></p><p>Arknights: Endfield blueprint [With Purification Node]. Copy share code EF012UO9i4aO08aEeIOo to use it in game. <span class="mark-grey">(Connect 1 Xircon Effluent conduit and 3 Sewage conduits as marked by the Control Ports.)</span></p><p>Arknights: Endfield blueprint [Without Purification Node]. Copy share code EF01A67uai873E2u9ieO to use it in game.</p><p><span class="mark-blue">After placing the Wuling City blueprints, connect 12 Fluid Pumps and 4 Inergen Pumps. Use one Fluid Pump per manifold port between the two Control Ports.</span></p><p><span class="mark-blue">Connect the free Conduit Outlet Manifold at the lower left to Xiragen returning from Yinglung Pass. Use inlet and outlet manifolds the entire way.</span><span class="mark-grey"> See the diagram below.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-555e37014be51d17.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="9IMOXkindePxrBRvntzId8"><p>External conduit connection diagram</p></div><p><span id="source-block-K05KTx8eryJLM7cUGCfWjA"></span></p><h3 id="yinglung-pass-awaiting-update" tabindex="-1">Yinglung Pass<span class="mark-grey"> (Awaiting Update)</span> <a class="header-anchor" href="#yinglung-pass-awaiting-update" aria-label="Permalink to &quot;Yinglung Pass&lt;span class=&quot;mark-grey&quot;&gt; (Awaiting Update)&lt;/span&gt;&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d1d877aa6abd6125.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="WrA3K3YY6PPDC9cxz6pSb2"><p>Xiranflow Cloudseeder layout</p></div><p><span class="mark-blue">Put the Automation-Core in the lower-left corner first.</span></p><p>Arknights: Endfield blueprint [Yinglung Pass 1]. Copy share code EF0170iOai69U515O0Ai to use it in game.</p><p><span class="mark-blue">Once blueprint 1 is down, move the Automation-Core into the layout. Orient it so the belts feed into it.</span></p><p>Arknights: Endfield blueprint [Yinglung Pass 2]. Copy share code EF01U9eE0e16AO5o71a8 to use it in game.</p><p>Arknights: Endfield blueprint [Yinglung Pass 3]. Copy share code EF01A67uai873E269ieO to use it in game.</p><p><span class="mark-blue">After placing the Jingyu Valley blueprints, connect the right-hand conduits from top to bottom: </span><span class="mark-red">2 Acid Pumps, 2 Acid Pumps, 2 Acid Pumps, 1 Fluid Pump, 1 Inergen Pump, Xiragen from Si&#39;s Painting, Xiragen from Cedar Forest, Xiragen returning to the main base, Xiragen from the North Wuling Exclusion Zone, and 1 Acid Pump.</span><span class="mark-grey"> See the diagram below.</span></p><p><span class="mark-grey">Leave the corresponding conduits unused if you skip Cedar Forest, Si&#39;s Painting, or the return to the main base.</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-df1b0c206dcc4686.jpeg" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="lkmMYdrY7dWCJ19fzWhach"><p>External conduit connection diagram</p></div><p><span id="source-block-rXAUvOhMy4Y2woR3qzI2D0"></span></p><h3 id="marker-stone-unused-with-a-few-small-modules-below-draft" tabindex="-1">Marker Stone (Unused, with a Few Small Modules Below)<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#marker-stone-unused-with-a-few-small-modules-below-draft" aria-label="Permalink to &quot;Marker Stone (Unused, with a Few Small Modules Below)&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h3><p><span id="source-block-xyp21BM8zSXkvpxADZimpL"></span></p><h2 id="frequently-asked-questions-draft" tabindex="-1">Frequently Asked Questions<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#frequently-asked-questions-draft" aria-label="Permalink to &quot;Frequently Asked Questions&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h2><p><span class="mark-red">Replacing the production line from its blueprint fixes most issues.</span></p><p><span class="mark-red"><strong>!!! Do not place the next blueprint while facilities from the previous blueprint are unfinished yellow construction ghosts. Craft and submit the facilities first, or the priority structure will break!!!</strong></span></p><p><span class="mark-red"><strong>!!! Do not make changes inside these production lines beyond those demonstrated in the video!!!</strong></span></p><p><span class="mark-grey"><strong>(including but not limited to: changing a control port&#39;s rate limit; modifying, re-placing, or deleting pipes and logistics components; modifying pipe/conduit connections; taking the Xiragen/Liquid Xiranite/Jincao Solution/Yazhen Solution out of the line) (if you want to modify something, ask in the group chat or in the bilibili comments)</strong></span></p><p><span class="mark-blue">When posting the production report for help in the group chat or Bilibili comments, always show the following items. You can star them to pin them at the top:</span></p><p><span class="mark-grey">(Draft)</span></p><p><span class="mark-blue"><strong>If you do not follow this, we may well ignore your question.</strong></span></p><ol><li>The line reaches maximum steady-state output once storage is <strong>full</strong> for Xiranite, Cuprium, Ferrium Powder, Separator Cores, Xircon, Hetonite Parts, and Hetonite. Output can exceed that steady rate while Cuprium Powder, Dense Originium Powder, Pyrrolite, and Ferrium are still in stock. Some starting conditions can waste a small amount of material before Xiranite and Cuprium fill. For example, when initial Xiranite stock is much lower than Cuprium stock, Cuprium consumption can be slightly below 510/min and Cuprium can fill while Xiranite is still below capacity. That is expected.</li></ol><p><span class="mark-red">2. Xiranite output below 360: Merge the 4 Fluid Pumps feeding the Jingyu Valley manifold in pairs. Never put 3 pumps on one port.</span></p><ol start="3"><li>If output drops below 360 after Xiranite storage fills, deposit priority at the Wuling City Liquid Xiranite oscillation module may have broken. See the repair section at the end.</li></ol><p><span id="source-block-t0z7G3tsyxdUHyGIQm8D63"></span></p><h2 id="troubleshooting-flowchart-draft" tabindex="-1">Troubleshooting Flowchart<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#troubleshooting-flowchart-draft" aria-label="Permalink to &quot;Troubleshooting Flowchart&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h2><p><span id="source-block-1LSrkaftkal04dlOuAVnMN"></span></p><h2 id="replacing-the-deposit-ports-for-wuling-city-s-liquid-xiranite-oscillation-module" tabindex="-1">Replacing the Deposit Ports for Wuling City&#39;s Liquid Xiranite Oscillation Module <a class="header-anchor" href="#replacing-the-deposit-ports-for-wuling-city-s-liquid-xiranite-oscillation-module" aria-label="Permalink to &quot;Replacing the Deposit Ports for Wuling City&#39;s Liquid Xiranite Oscillation Module&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-32517f63cbda7bdf.q90-ecc32e8c154b7810.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-xRZ15q1NkWBTmB1JDA4RWn"></span></p><h2 id="reference-diagrams-for-long-distance-external-conduits" tabindex="-1">Reference Diagrams for Long-Distance External Conduits <a class="header-anchor" href="#reference-diagrams-for-long-distance-external-conduits" aria-label="Permalink to &quot;Reference Diagrams for Long-Distance External Conduits&quot;">​</a></h2><p><span id="source-block-I6zAY6W2XBcbVSabVa6w2s"></span></p><h3 id="north-wuling-exclusion-zone" tabindex="-1">North Wuling Exclusion Zone <a class="header-anchor" href="#north-wuling-exclusion-zone" aria-label="Permalink to &quot;North Wuling Exclusion Zone&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2f09bcd3d15b849d.q90-aca6a5ee9222b010.webp" alt="1.6 Automatic Maximum Gross Production"></p><div class="logistics-image-caption" data-source-block="dKqRdIglNrkgMrjpBFqDDk"><p>Yinglung Pass Xiragen connections</p></div><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-7ed15289ffeacc9c.q90-899dc838aff2d2a0.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9e171bac57e90c75.q90-afaeee960e8ec8ac.webp" alt="Image"></td></tr></tbody></table><p><span class="mark-grey">The left option allows direct teleportation but needs an extra pair of conduits; the right requires traveling across the map and saves a pair of conduits.</span></p><p><span id="source-block-w3yu6U9kFlDJ0eY8fMPtFO"></span></p><h3 id="si-s-painting" tabindex="-1">Si&#39;s Painting <a class="header-anchor" href="#si-s-painting" aria-label="Permalink to &quot;Si&#39;s Painting&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a30aa3f7d5114446.q90-fcb1e0c41a66d3bd.webp" alt="1.6 Automatic Maximum Gross Production"></p><p><span id="source-block-QzBDMppg4dTZloLyKk0roH"></span></p><h3 id="purification-node" tabindex="-1">Purification Node <a class="header-anchor" href="#purification-node" aria-label="Permalink to &quot;Purification Node&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-01c55e9cfb85b796.q90-8c17eea89d32ac73.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-48a24d11b68d1542.q90-3e8754fa054b5719.webp" alt="Image"></td><td></td></tr></tbody></table><p><span id="source-block-SomZorxQ0OrMRgivJFg5SX"></span></p><h2 id="discretionary-withdrawals-draft" tabindex="-1">Discretionary Withdrawals<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#discretionary-withdrawals-draft" aria-label="Permalink to &quot;Discretionary Withdrawals&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h2><p>Withdrawal ports can draw Cuprium, Xiranite, Heavy Xiranite, Hetonite, or Pyrrolite.</p><p>Too many withdrawal ports can starve the Xircon line of Xiranite or the Separator Core line of Xiranite or Cuprium. <strong>Watch whether stocks of Separator Cores or Xircon decline.</strong> If they hold steady, the withdrawals are fine.</p><p>If you&#39;re unsure, place at most 2 withdrawal ports per item type.</p><p><span id="source-block-JLWlEFLFuKU9UAR4Iqu7dA"></span></p><h3 id="expanding-the-range-of-discretionary-withdrawals-draft" tabindex="-1">Expanding the Range of Discretionary Withdrawals<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#expanding-the-range-of-discretionary-withdrawals-draft" aria-label="Permalink to &quot;Expanding the Range of Discretionary Withdrawals&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h3><p><span id="source-block-ejQJ5h4tB1dkvkfIxNIgn2"></span></p><h2 id="performance-overview-draft" tabindex="-1">Performance Overview<span class="mark-grey"> (Draft)</span> <a class="header-anchor" href="#performance-overview-draft" aria-label="Permalink to &quot;Performance Overview&lt;span class=&quot;mark-grey&quot;&gt; (Draft)&lt;/span&gt;&quot;">​</a></h2></div>',1)])])}const g=a(o,[["render",s]]);export{h as __pageData,g as default};
